import React, { useState, useRef, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import PaymentModal from '../components/paymentModal';
import Navbar from '../components/Navbar';
import { LanguageContext } from '../context/LanguageContext';
import { API_URL } from '../config';

const DOMAIN_LABELS = {
  red_team: { fr: 'Red Team', en: 'Red Team' },
  blue_team: { fr: 'Blue Team', en: 'Blue Team' },
  grc: { fr: 'GRC', en: 'GRC' },
};
const LEVEL_LABELS = {
  beginner: { fr: 'Débutant', en: 'Beginner' },
  intermediate: { fr: 'Intermédiaire', en: 'Intermediate' },
  advanced: { fr: 'Avancé', en: 'Advanced' },
};

const Home = () => {
  const { language, t } = useContext(LanguageContext);
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [search, setSearch] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const searchRef = useRef(null);

  useEffect(() => {
    const handleKey = (e) => { if (e.key === '/') { e.preventDefault(); searchRef.current?.focus(); } };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, []);

  useEffect(() => {
    fetch(`${API_URL}/courses/`)
      .then(res => { if (!res.ok) throw new Error('Impossible de charger les parcours.'); return res.json(); })
      .then(data => setCourses(data))
      .catch(err => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  const suggestions = search.length > 0 ? courses.filter(c => t(c, 'title_fr', 'title_en').toLowerCase().includes(search.toLowerCase())) : [];

  return (
    <div className="min-h-screen text-white font-sans">
      <Navbar />

      <section className="relative border-b border-slate-800/60">
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[600px] h-[300px] bg-blue-600/20 blur-[120px] rounded-full"></div>
        </div>

        <div className="relative max-w-4xl mx-auto text-center px-6 py-24">
          <span className="inline-block text-[11px] font-semibold tracking-wide text-blue-400 bg-blue-500/10 border border-blue-500/20 rounded-full px-4 py-1.5 mb-8">
            {language === 'fr' ? 'Écosystème académique international' : 'International academic ecosystem'}
          </span>
          <h1 className="text-4xl md:text-6xl font-extrabold leading-tight mb-6">
            {language === 'fr' ? 'Déployez vos compétences d\'élite avec' : 'Deploy your elite skills with'}<br />
            <span className="bg-gradient-to-r from-blue-400 to-cyan-300 bg-clip-text text-transparent">GUARDIAN CYBER LABS</span>
          </h1>
          <p className="text-slate-400 max-w-xl mx-auto mb-10 text-base leading-relaxed">
            {language === 'fr'
              ? 'Red Team, Blue Team, GRC — une formation pratique en cybersécurité, portée par AVALON SECURE.'
              : 'Red Team, Blue Team, GRC — practical cybersecurity training, powered by AVALON SECURE.'}
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-3 mb-10">
            <Link to="/catalog" className="w-full sm:w-auto bg-blue-600 hover:bg-blue-500 text-white font-semibold px-8 py-3.5 rounded-lg transition-colors shadow-lg shadow-blue-600/20">
              {language === 'fr' ? 'Explorer les parcours' : 'Explore courses'}
            </Link>
            <a href="https://mail.google.com/mail/?view=cm&fs=1&to=avalonsecure7@gmail.com&su=Contact%20Guardian%20Cyber%20Labs" target="_blank" rel="noopener noreferrer"
              className="w-full sm:w-auto bg-slate-800/60 hover:bg-slate-800 border border-slate-700 text-slate-200 font-semibold px-8 py-3.5 rounded-lg transition-colors">
              {language === 'fr' ? 'Nous contacter' : 'Contact us'}
            </a>
          </div>

          <div className="relative max-w-md mx-auto z-20">
            <input
              ref={searchRef}
              value={search}
              onChange={(e) => { setSearch(e.target.value); setShowSuggestions(true); }}
              onFocus={() => setShowSuggestions(true)}
              onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
              placeholder={language === 'fr' ? 'Rechercher un parcours...' : 'Search a course...'}
              className="w-full bg-slate-900/80 border border-slate-700 rounded-full pl-5 pr-12 py-3 text-sm text-white placeholder:text-slate-500 outline-none focus:border-blue-500 transition-colors"
            />
            <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] text-slate-500 border border-slate-700 rounded px-1.5 py-0.5">/</span>

            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-slate-900 border border-slate-700 rounded-xl overflow-hidden shadow-2xl z-30 text-left">
                {suggestions.map(c => (
                  <Link key={c.id} to={`/course/${c.id}`} className="block px-5 py-3 hover:bg-slate-800 transition-colors border-b border-slate-800 last:border-0">
                    <p className="text-sm font-semibold text-white">{t(c, 'title_fr', 'title_en')}</p>
                    <p className="text-xs text-slate-500">{c.is_free ? (language === 'fr' ? 'Gratuit' : 'Free') : `$${c.price}`}</p>
                  </Link>
                ))}
              </div>
            )}
          </div>
        </div>
      </section>

      <section className="relative max-w-6xl mx-auto px-6 py-20">
        <div className="flex items-center justify-between mb-10">
          <h2 className="text-2xl font-bold">{language === 'fr' ? 'Nos parcours' : 'Our courses'}</h2>
          <Link to="/catalog" className="text-sm font-semibold text-blue-400 hover:text-blue-300 transition-colors">
            {language === 'fr' ? 'Voir tout le catalogue →' : 'View full catalog →'}
          </Link>
        </div>

        {loading ? (
          <p className="text-slate-500 text-sm">{language === 'fr' ? 'Chargement des parcours...' : 'Loading courses...'}</p>
        ) : error ? (
          <p className="text-red-400 text-sm">{error} — vérifie que le serveur backend tourne bien sur {API_URL}.</p>
        ) : (
          <div className="grid md:grid-cols-3 gap-6">
            {courses.slice(0, 6).map(course => (
              <div key={course.id} className="group bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden hover:border-blue-500/40 hover:bg-slate-900 transition-all duration-300 shadow-xl flex flex-col">
                <div className="relative h-40 overflow-hidden">
                  <img src={course.thumbnail_url || 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=600'} alt={t(course, 'title_fr', 'title_en')} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                  {course.is_bestseller && <span className="absolute top-3 left-3 bg-amber-400 text-slate-900 text-[10px] font-bold uppercase tracking-wide px-2.5 py-1 rounded">{language === 'fr' ? 'Meilleure vente' : 'Bestseller'}</span>}
                </div>
                <div className="p-6 flex flex-col justify-between flex-1">
                  <div>
                    <div className="flex items-center gap-2 mb-3 flex-wrap">
                      <span className="text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full bg-blue-500/10 text-blue-400">
                        {DOMAIN_LABELS[course.domain]?.[language] || course.domain}
                      </span>
                      <span className="text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full bg-slate-800 text-slate-400">
                        {LEVEL_LABELS[course.level]?.[language] || course.level}
                      </span>
                    </div>
                    <h3 className="text-lg font-bold mb-1 leading-snug group-hover:text-blue-400 transition-colors">{t(course, 'title_fr', 'title_en')}</h3>
                    {course.instructor_name && <p className="text-xs text-slate-500 mb-2">{language === 'fr' ? 'Par' : 'By'} {course.instructor_name}</p>}
                    <p className="text-slate-400 text-sm leading-relaxed mb-6">{t(course, 'description_fr', 'description_en')}</p>
                  </div>
                  <div className="flex gap-3 items-center justify-between">
                    <span className="text-sm font-mono text-blue-400 font-bold">{course.is_free ? (language === 'fr' ? 'Gratuit' : 'Free') : `$${course.price}`}</span>
                    <div className="flex gap-2">
                      <Link to={`/course/${course.id}`} className="text-center border border-slate-700 hover:border-slate-500 text-slate-300 hover:text-white font-semibold py-2.5 px-4 rounded-lg text-sm transition-colors">
                        {language === 'fr' ? 'Détails' : 'Details'}
                      </Link>
                      <button onClick={() => setSelectedCourse(course)} className="bg-blue-600 hover:bg-blue-500 text-white font-semibold py-2.5 px-4 rounded-lg text-sm transition-colors">
                        {course.is_free ? (language === 'fr' ? 'Accéder' : 'Access') : (language === 'fr' ? 'Débloquer' : 'Unlock')}
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {selectedCourse && <PaymentModal course={selectedCourse} onClose={() => setSelectedCourse(null)} />}
    </div>
  );
};
export default Home;
